import { Link } from "react-router-dom";

export default function GameCard({game}){
  return(
    <Link to={`/game/${game._id}`}>
      <div className="card">
        <img src={game.thumbnail}/>
        <p style={{padding:"8px"}}>{game.title}</p>
      </div>
    </Link>
  );
}
